def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    fg = [c for c in colors if c != bg]
    if not fg:
        return [row[:] for row in grid]
    color = max(fg, key=lambda c: sum(row.count(c) for row in grid))

    active = [any(v == color for v in row) for row in grid]
    spans = []
    start = None
    for r, yes in enumerate(active + [False]):
        if yes and start is None:
            start = r
        elif not yes and start is not None:
            spans.append((start, r))
            start = None

    out = [row[:] for row in grid]
    if len(spans) >= 2:
        (a, b), (c, d) = spans[0], spans[-1]
        if b - a == d - c:
            count1 = sum(grid[r][j] == color for r in range(a, b) for j in range(w))
            count2 = sum(grid[r][j] == color for r in range(c, d) for j in range(w))
            if count1 >= count2:
                src, dst = a, c
            else:
                src, dst = c, a
            for dr in range(b - a):
                for j in range(w):
                    if grid[src + dr][j] == color and grid[dst + dr][j] == bg:
                        out[dst + dr][j] = 1
    return out
